const raw = $input.first().json.output || $input.first().json.text || '';
const description = $node['Webhook Trigger'].json.body?.description || '';
const threadHistory = $node['Webhook Trigger'].json.body?.thread_history || '';
const subject = $node['Webhook Trigger'].json.body?.subject || '';
const emailBody = [subject, description, threadHistory].filter(Boolean).join('\n---\n');

let parsed = { gp_id: null, phone: null, language: "english", query_text: raw, intent: "general", ticket_type: "L1_Queries" };
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {}

// Debug fields — always populated
parsed.override_triggered = false;
parsed.override_reason = null;
parsed.gpt_original_intent = parsed.intent;

// GP ID regex
const gpPatterns = [
  /GP\s*(?:ID|id|Id)\s*[:\-\s]+([A-Za-z0-9]+)/i,
  /GP\s*id\s+is\s+([A-Za-z0-9]+)/i,
  /main\s+([A-Z][A-Z0-9]{5,10})\s+hoon/i,
  /\b([A-Z]\d[A-Z][A-Z]\d{4})\b/,
  /\b([A-Z]{1,2}\d[A-Z]{1,2}\d{4,5})\b/
];
for (const p of gpPatterns) {
  const m = emailBody.match(p);
  if (m && m[1] && m[1].length >= 6) { parsed.gp_id = m[1]; break; }
}
const phoneMatch = emailBody.match(/\b([6-9]\d{9})\b/);
if (phoneMatch) parsed.phone = phoneMatch[1];

// ============================================
// AGENT_HANDLED override — tightened
// ============================================
if (parsed.intent === 'agent_handled') {
  const th = threadHistory;
  const tc = parseInt($node['Webhook Trigger'].json.body?.thread_count || '0');

  // Require an actual sender line with @gromo.in, not just substring anywhere
  const hasGromoSender = /from:\s*[^\n]*@gromo\.in/i.test(th) ||
                         /<[a-z0-9._-]+@gromo\.in>/i.test(th);

  if (tc < 2 || !hasGromoSender) {
    parsed.override_triggered = true;
    parsed.override_reason = tc < 2
      ? `thread_count=${tc} (need >=2)`
      : 'no From: @gromo.in sender line found in thread_history';

    const q = (parsed.query_text || emailBody).toLowerCase();

    // Specific intent matches first
    if (q.match(/insurance|bima|posp|motor|life insurance|health insurance/)) parsed.intent = 'insurance';
    else if (q.match(/pos\s+verification|pos\s+failure|noc/)) parsed.intent = 'pos_noc';
    else if (q.match(/delete\s+account|deactivate|close\s+my\s+account|account\s+band/)) parsed.intent = 'account_delete';
    else if (q.match(/protect\s+plan|protect\s+membership|gromo\s+protect/)) parsed.intent = 'membership';
    else if (q.match(/lead|payout|pending\s+lead|expired\s+lead|dispute|claim|sale\s+not\s+tracked/)) parsed.intent = 'leads';
    else if (q.match(/hdfc|icici|bajaj|kotak|upstox|tide|axis|sbi/)) parsed.intent = 'search_product';
    else if (q.match(/profile|bank\s+detail/)) parsed.intent = 'profile';
    else if (q.match(/wallet|balance|deducted|withdraw|kyc|earning/)) parsed.intent = 'wallet';
    // No keyword matched AND no identifiers → let Ask Info branch handle it
    else if (!parsed.gp_id && !parsed.phone) {
      parsed.intent = 'general';
      parsed.ticket_type = 'Did Not Explain Query';
    }
    else parsed.intent = 'wallet';  // last resort: identifiers exist but no keywords matched
  }
}

// ============================================
// TICKET TYPE validation + fallback
// ============================================
const VALID_TYPES = new Set([
  "Lead syncing","Payout Syncing","Rejected","Workable Cases","Blank Email/ Junk/ Test",
  "GroMo Membership","Protect related information","Protect disputes",
  "Unable To Use/Understand Gromo App","Offer/Scratch Card Related Dispute - Genuine Issue",
  "App Kyc Issue","Account Deactivation Request/Account Reactivate",
  "Details Modification / Detail Remove","App Bugs","Start Working With Gromo",
  "How To Create Lead","How To Open The Account","Unable To Share The Link/Proceed Further",
  "Brand Kyc Related","Agency Related Query","Training Related Query","Refer And Earn",
  "Loan","Credit Card","Job Loss","Demat","Saving Account","Subscription",
  "Credit Pay Later","Investment","Others Brand","POS Related","Insurance Lead Status",
  "Payout Status - Within 10 Days Of Lead Creation","Payout Status - After 10 Days Of Lead Creation",
  "Lead Expire","Dispute Related","Wallet Transfer Issue","Negative Payout Related",
  "2nd Kpi Payout Related","Refer And Earn Payout Related","Duplicate Email",
  "Did Not Explain Query","TDS Document/NOC Certificate","IVRS Blocked","General Query",
  "Marketing Email","Insurance Related Information","Wants To Know About Current Offers",
  "Scratch Card Enquiry","Offer/Scratch Card Related Dispute - Gp Understanding Problem",
  "Required Lead Details","Gromo Coins","Gromo Bazaar","Wallet Expire",
  "Income Express / Protect Deactivation","L1_Queries"
]);

// Intent-based fallback if GPT gave invalid value
const INTENT_FALLBACK = {
  insurance: "Insurance Related Information",
  pos_noc: "POS Related",
  account_delete: "Account Deactivation Request/Account Reactivate",
  wallet: "General Query",
  leads: "Payout Syncing",
  products: "General Query",
  membership: "Protect related information",
  profile: "Details Modification / Detail Remove",
  search_product: "Others Brand",
  agent_handled: "L1_Queries",
  general: "Did Not Explain Query"
};

if (!parsed.ticket_type || !VALID_TYPES.has(parsed.ticket_type)) {
  parsed.ticket_type = INTENT_FALLBACK[parsed.intent] || "L1_Queries";
}

// Force L2 types if intent is L2, regardless of what GPT said
if (parsed.intent === 'insurance' && parsed.ticket_type !== "Insurance Related Information") {
  parsed.ticket_type = "Insurance Related Information";
}
if (parsed.intent === 'pos_noc') {
  const q = (parsed.query_text || emailBody).toLowerCase();
  parsed.ticket_type = q.includes('noc') || q.includes('tds') ? "TDS Document/NOC Certificate" : "POS Related";
}
if (parsed.intent === 'account_delete') {
  parsed.ticket_type = "Account Deactivation Request/Account Reactivate";
}

// Debug summary for execution log
parsed._debug = {
  thread_count: parseInt($node['Webhook Trigger'].json.body?.thread_count || '0'),
  thread_history_length: threadHistory.length,
  thread_history_has_gromo_substring: threadHistory.toLowerCase().includes('@gromo.in'),
  thread_history_has_gromo_sender: /from:\s*[^\n]*@gromo\.in/i.test(threadHistory) ||
                                   /<[a-z0-9._-]+@gromo\.in>/i.test(threadHistory),
  override_triggered: parsed.override_triggered,
  override_reason: parsed.override_reason,
  gpt_original_intent: parsed.gpt_original_intent,
  final_intent: parsed.intent
};

return [{ json: { output: parsed } }];

