  leads = apiData.data;
} else if (apiData.leads && Array.isArray(apiData.leads)) {
  leads = apiData.leads;
} else if (Array.isArray(apiData)) {
  leads = apiData;
}

const today = new Date();
const enrichedLeads = leads.map(lead => {
  const createdAt = new Date(lead.createdAt || lead.created_at || lead.createdDate);
  let workingDays = 0;

  if (!isNaN(createdAt.getTime())) {
    const current = new Date(createdAt);
    while (current < today) {
      current.setDate(current.getDate() + 1);
      const day = current.getDay();
      if (day !== 0 && day !== 6) {
        workingDays++;
      }
    }
  }

  let leadAgeCategory = 'unknown';
  const totalDays = Math.floor((today - new Date(lead.createdAt || lead.created_at || lead.createdDate)) / (1000 * 60 * 60 * 24));

  if (totalDays > 30) {
    leadAgeCategory = 'EXPIRED_OVER_30_DAYS';
  } else if (workingDays < 10) {
    leadAgeCategory = 'LESS_THAN_10_WORKING_DAYS';
  } else {
    leadAgeCategory = 'MORE_THAN_10_WORKING_DAYS';
  }

  // Dispute surfacing: make the AI unable to miss protect/dispute context
  const protectStatus = lead.protectLeadStatus || lead.disputeStatus || lead.claimStatus || '';
  const disputeReasonRaw = lead.displayText || lead.rejectionReason || lead.disputeReason || '';
  const hasDispute = !!(protectStatus || disputeReasonRaw);
  const isLimitExhausted = /limit|quota|exhaust|breach/i.test(disputeReasonRaw) ||
                           /limit|quota|exhaust|breach/i.test(protectStatus);

  return {
    ...lead,
    _workingDaysSinceCreation: workingDays,
    _totalDaysSinceCreation: totalDays,
    _leadAgeCategory: leadAgeCategory,
    _hasDispute: hasDispute,
    _protectStatus: protectStatus,
    _disputeReason: disputeReasonRaw,
    _isLimitExhausted: isLimitExhausted
  };
});

return [{ json: { api_data: { data: enrichedLeads }, fallback_used: false, working_days_calculated: true } }];

