// Circuit breaker — if a ticket has more than 10 threads, something is wrong, never auto-reply
const threadCountCheck = parseInt($input.first().json.thread_count || '0');
if (threadCountCheck > 10) {
  return [{ json: { ticket_id: ticketId, skipped: true, reason: `runaway thread count ${threadCountCheck}, manual review required` } }];
}

